 facethefuture:{name:'Face the Future',type:'psychic',cost:3,tgt:'none',art:'👁️',kw:['ability'],abil:'facethefuture',text:V=>'Before each card draw, '+DC_SCRY+' X, where X is the number of cards you are about to draw.'},
 overwhelm:{name:'Overwhelm',type:'psychic',cost:1,tgt:'enemy',art:'🧠',can:r=>r.dc.draw.length>0,text:V=>'Reveal the top card of your draw pile. Apply Vulnerable equal to its base AP cost, plus 1, to one enemy. You may put the revealed card on the bottom of your deck.',run:c=>{const u=c.dc.draw[0];if(!u)return;const d=dcDefOf(dcInst(c.r,u).d);if(c.foe())c.vuln(c.target,(d.cost||0)+1);c.post({k:'overwhelm',u})}},
 simplebeam:{name:'Simple Beam',type:'psychic',cost:1,tgt:'enemy',art:'📡',text:V=>'Apply Enfeebled 2 to one enemy. Until your next turn, that enemy cannot perform Charged attacks or inflict debuffs.',run:c=>{const f=c.foe();if(!f)return;c.enfeeble(c.target,2);f.beam=1}},
 premonition:{name:'Premonition',type:'psychic',cost:1,tgt:'self',art:'🌠',text:V=>DC_SCRY+' 3. Gain '+V(4,'blk')+' Block, plus '+V(2,'blk')+' Block for each card you moved to the bottom of your deck.',run:c=>{if(c.dc.draw.length)c.post({k:'scry',n:3,blk:c.inst.u});else c.block(4)}},
 rehearsal:{name:'Rehearsal',type:'psychic',cost:0,tgt:'none',art:'🎭',kw:['exile'],pre:'hand1',preTitle:'PUT WHICH CARD ON TOP?',can:r=>r.dc.hand.length>1,text:V=>'Put another card from your hand on top of your draw pile. The next time you draw that card this turn, it costs 1 less until the turn ends, to a minimum of 0. '+DC_EX+' this card.',run:c=>{const u=c.choice&&c.choice.cards&&c.choice.cards[0];if(!u||!c.dc.hand.includes(u))return;c.dc.hand=c.dc.hand.filter(x=>x!==u);c.dc.draw.unshift(u);c.dc.rehearse.push(u)}},
 calculatedrisk:{name:'Calculated Risk',type:'psychic',cost:1,tgt:'self',art:'🎲',pre:async r=>{if(!r.dc.draw.length)return {};const k=await dcChooseOpt('PREDICT THE TOP CARD’S BASE COST',['0–1 AP','2 or more AP']);if(k==null)return null;return {pred:k}},text:V=>'Predict whether the top card of your deck has a base AP cost of 0–1 or 2 or more, then draw it. If correct, gain '+V(10,'blk')+' Block. Otherwise, gain '+V(3,'blk')+' Block.',run:c=>{const u=c.dc.draw[0],d=u&&dcDefOf(dcInst(c.r,u).d),hi=!!d&&(d.cost||0)>=2,right=!!d&&c.choice&&c.choice.pred!=null&&((c.choice.pred===1)===hi);if(u)c.draw(1,1);c.block(right?10:3)}},
 futuresight:{name:'Future Sight',type:'psychic',cost:1,tgt:'enemy',art:'🔭',text:V=>'Choose one enemy. At the start of your next turn, deal '+V(13,'dmg')+' damage to it. If it has fainted, target the remaining enemy with the lowest HP.',run:c=>{if(c.foe())c.dc.fsight.push({i:c.target,d:c.eff(13,'dmg')})}},
