 swarmsignal:{name:'Swarm Signal',type:'bug',cost:2,tgt:'none',art:'🐝',kw:['ability'],abil:'swarmsignal',text:V=>'The first time each turn you deal at least 3 hits to the same enemy, deal 5 extra damage to it.'},
 feedtheswarm:{name:'Feed the Swarm',type:'bug',cost:2,tgt:'self',art:'🐛',kw:['exile'],pre:'plant1',can:r=>r.dc.field.length>0,text:V=>'Remove all Plant counters from one of your Planted cards. Gain 1 Strength and '+V(4,'blk')+' Block for each counter removed. '+DC_EX+' this card.',run:c=>{const p=c.dc.field.find(x=>x.u===(c.choice&&c.choice.plant));if(!p)return;const n=p.n;p.n=0;dcPlantGone(c.r,n);if(n>0){c.selfSt('str',n);c.block(4*n)}}},
 twineedle:{name:'Twineedle',type:'bug',cost:1,tgt:'enemy',art:'🪡',atk:1,text:V=>'Deal '+V(3,'dmg')+' damage to one enemy and apply Poison 1, then repeat both effects against that enemy.',run:c=>{const t=c.foe()?c.target:null;if(t==null)return;for(let k=0;k<2;k++){const f=c.dc.foes[t];if(!f||f.hp<=0)break;const h=c.hit(t,3);if(h&&!h.ko)c.poison(t,1)}}},
 megahorn:{name:'Megahorn',type:'bug',cost:2,tgt:'enemy',art:'🦏',atk:1,text:V=>'Deal '+V(10,'dmg')+' damage to one enemy. Deal '+V(4,'dmg')+' additional damage for each different enemy you hit earlier this turn.',run:c=>{const n=Object.keys(c.dc.hitsOn||{}).filter(k=>c.dc.hitsOn[k]>0).length;c.dmg(c.target,10+4*n)}},
 silkcocoon:{name:'Silk Cocoon',type:'bug',cost:1,tgt:'self',art:'🐛',cocoon:1,pre:'hand1',preTitle:'PUT WHICH CARD IN THE COCOON?',can:r=>r.dc.hand.length>1,text:V=>'Gain '+V(8,'blk')+' Block. Place another card from your hand underneath this card. At the start of your next turn, return that card to your hand with its AP cost reduced by 1 for that turn, to a minimum of 0. Then discard Silk Cocoon.',run:c=>{c.block(8);const u=c.choice&&c.choice.cards&&c.choice.cards[0];let held=null;if(u&&c.dc.hand.includes(u)){c.dc.hand=c.dc.hand.filter(x=>x!==u);held=u}c.dc.cocoons.push({u:c.inst.u,held})}},
 shedskin:{name:'Shed Skin',type:'bug',cost:1,tgt:'self',art:'🐍',pre:'handN',preTitle:'SHED SKIN: DISCARD UP TO 2',preMax:2,text:V=>'Discard up to 2 cards. Gain '+V(3,'blk')+' Block for each card discarded, then draw that many cards. Remove 1 stack of a debuff from yourself for each card discarded.',run:c=>{const n=c.discardChosen();if(!n)return;c.block(3*n);c.draw(n);for(let k=0;k<n;k++)dcCleanse1(c.r)}},
 encircle:{name:'Encircle',type:'bug',cost:1,tgt:'self',art:'⭕',text:V=>'Gain '+V(3,'blk')+' Block for each different enemy you have hit this turn. If you hit every living enemy this turn, draw 1 card.',run:c=>{const hit=Object.keys(c.dc.hitsOn||{}).filter(k=>c.dc.hitsOn[k]>0).map(Number);if(hit.length)c.block(3*hit.length);const al=c.dc.foes.map((f,i)=>f.hp>0?i:-1).filter(i=>i>=0);if(al.length&&al.every(i=>hit.includes(i)))c.draw(1)}},
