 stonevault:{name:'Stone Vault',type:'rock',cost:1,tgt:'self',art:'🏦',text:V=>'Set aside up to 10 of your current Block, removing it from your Block total. Immediately after your next Block reset, return exactly that amount to your Block total.',run:c=>{const n=Math.min(10,c.dc.pb);c.dc.pb-=n;c.dc.vault=(c.dc.vault||0)+n}},
 avalanche:{name:'Avalanche',type:'rock',cost:2,tgt:'none',art:'🏔️',atk:1,text:V=>'Lose all your Block. Deal damage equal to half the amount lost, rounded down, to every enemy.',run:c=>{const n=c.dc.pb;c.dc.pb=0;const d=Math.floor(n/2);if(d)c.dmgAll(d)}},
 standingstone:{name:'Standing Stone',type:'rock',cost:2,tgt:'none',art:'🗿',kw:['ability'],abil:'standingstone',text:V=>'After your start-of-turn Block reset and scheduled Block returns resolve, gain 1 Strength if you have at least 8 Block.'},
 weatheredwall:{name:'Weathered Wall',type:'rock',cost:1,tgt:'self',art:'🧱',text:V=>'Gain '+V(6,'blk')+' Block. If you have Block immediately before your next Block reset, gain '+V(5,'blk')+' Block immediately after the reset.',run:c=>{c.block(6);c.dc.wwall=(c.dc.wwall||0)+c.eff(5,'blk')}},
