 pallbearer:{name:'Pallbearer',type:'ghost',cost:1,tgt:'self',art:'⚰️',pre:'hand1',preTitle:'GIVE WHICH CARD ISEKAI?',preOk:(r,u)=>!dcIsMorbid(r,u)&&!r.dc.isekai.includes(u),can:r=>r.dc.hand.length>1,text:V=>'Gain '+V(6,'blk')+' Block. Give another non-Morbid card in your hand '+DC_ISEKAI+'.',run:c=>{c.block(6);const u=c.choice&&c.choice.cards&&c.choice.cards[0];if(u&&c.dc.hand.includes(u))dcGiveIsekai(c.r,u)}},
 borrowedsoul:{name:'Borrowed Soul',type:'ghost',cost:1,tgt:'none',art:'👻',kw:['exile'],pre:'void1',can:r=>r.dc.void.some(u=>dcSoulOk(r,u)),text:V=>'Return a non-Morbid, non-Ability card from the Void to your hand. Give it '+DC_MORBID+' and “Exile after playing” for the rest of combat. '+DC_EX+' this card.',run:c=>{const u=c.choice&&c.choice.cards&&c.choice.cards[0];if(!u||!c.dc.void.includes(u))return;c.dc.void=c.dc.void.filter(x=>x!==u);c.dc.hand.push(u);c.dc.morbidU.push(u);c.dc.exileU.push(u)}},
 funeralveil:{name:'Funeral Veil',type:'ghost',cost:1,tgt:'self',art:'🕯️',pre:'hand1',can:r=>r.dc.hand.length>1,text:V=>DC_EX+' another card from your hand. Gain Block equal to '+V(4,'blk')+' plus four times that card’s base AP cost.',run:c=>{const u=c.choice&&c.choice.cards&&c.choice.cards[0],d=u&&dcDefOf(dcInst(c.r,u).d);if(c.exileChosen())c.block(4+4*((d&&d.cost)||0))}},
 lastrites:{name:'Last Rites',type:'ghost',cost:1,tgt:'enemy',art:'🪦',text:V=>'Mark one enemy for this turn. If it faints, choose a non-Morbid card in your discard pile and return it to your hand. Gain 1 AP.',run:c=>{const f=c.foe();if(f)f.rites=1}},
 unfinishedbusiness:{name:'Unfinished Business',type:'ghost',cost:1,tgt:'enemy',art:'📜',atk:1,kw:['brittle'],brittleNow:1,text:(V,r,inst)=>'Deal '+V(7,'dmg')+' damage to one enemy. '+(r&&r.dc&&inst&&r.dc.noBrittle.includes(inst.u)?'':DC_BRITTLE+'. Give this card Isekai before resolving the discard or Exile that triggered Brittle. This Brittle effect can activate only once per combat.'),run:c=>c.dmg(c.target,7)},
 // Dragon
 dragonsdescent:{name:'Dragon’s Descent',type:'dragon',cost:4,tgt:'enemy',art:'🐉',atk:1,costMod:r=>r.dc.apLeft>=1?-1:0,text:V=>'Deal '+V(26,'dmg')+' damage to one enemy and gain '+V(8,'blk')+' Block. Costs 1 less if you ended your last turn with at least 1 AP unspent.',run:c=>{c.dmg(c.target,26);c.block(8)}},
 hoard:{name:'Hoard',type:'dragon',cost:1,tgt:'none',art:'💰',kw:['retain','exile'],text:V=>'End your turn. Gain additional AP next turn equal to the AP you had remaining after paying for this card, up to 2. '+DC_EX+' this card.',run:c=>{c.dc.hoard=(c.dc.hoard||0)+Math.min(2,c.dc.ap);c.dc.endNow=1}},
