 Melmetal:{icon:'🔩',rule:'Double Iron Bash: its multi-hit attack gains 1 hit every time it uses it, up to 3 hits. After each Bash, Melmetal cools down and won’t act for a turn.'},
 Celebi:{icon:'⏳',rule:'Time Travel: every 3rd turn it rewinds its HP to what it was 2 turns ago.'},
 Manaphy:{icon:'💗',rule:'Heart Swap: every 3rd turn it swaps its debuffs with your team’s.'},
 Diancie:{icon:'💎',rule:'Diamond Shell: starts with 30 Block, and its Block never runs out at the start of its turn.',start:f=>{f.blk=30}},
