// tuning: multiples of the boss's attack (c) · Aggron alternates Fortify / Siege Breaker · Gardevoir: mark → light → land → light (recovery) → mark…
const DC_HB={Aggron:{hp:1.1,atk:.86,blk:1.7,base:.75,per:.5},Gardevoir:{hp:1.05,atk:1.45,fs:2.3,light:.7},Tinkaton:{hp:.9,atk:1.2,light:.75,ham:1.05,vuln:2},Volcarona:{hp:1.1,atk:1.45,light:.75,sweep:.5,weak:.6,need:12}};
